static inline uint32_t nofrendo_crc32(const void *data, size_t len)
{
const uint8_t *p = (const uint8_t *)data;
uint32_t crc = 4294967295u;
for (size_t i = 0; i < len; i++)
{
crc ^= p[i];
for (int b = 0; b < 8; b++)
crc = (crc >> 1) ^ (3988292384u & (uint32_t)(-(int32_t)(crc & 1u)));
}
return ~crc;
}
