static uint8 regs[4];
static uint8 latch = 0;
static int bitcount = 0;
static int prg_banks = 0;
static void update_mirror()
{
switch (regs[0] & 3)
{
case 0: ppu_setmirroring(PPU_MIRROR_SCR0); break;
case 1: ppu_setmirroring(PPU_MIRROR_SCR1); break;
case 2: ppu_setmirroring(PPU_MIRROR_VERT); break;
case 3: ppu_setmirroring(PPU_MIRROR_HORI); break;
}
}
static void update_chr()
{
if (regs[0] & 16)
{
mmc_bankvrom(4, 0, regs[1]);
mmc_bankvrom(4, 4096, regs[2]);
}
else
{
mmc_bankvrom(8, 0, regs[1] >> 1);
}
}
static void update_prg()
{
int offset = prg_banks >= 16 ? (regs[1] & 16) : 0;
int bank = regs[3] & 15;
int mode = (regs[0] >> 2) & 3;
switch (mode)
{
case 0:
case 1:
mmc_bankrom(32, 32768, offset + (bank >> 1));
break;
case 2:
mmc_bankrom(16, 32768, offset);
mmc_bankrom(16, 49152, offset + bank);
break;
case 3:
mmc_bankrom(16, 32768, offset + bank);
mmc_bankrom(16, 49152, offset + ((prg_banks - 1) & 15));
break;
}
}
static void map_write(uint32 address, uint8 value)
{
if (value & 128)
{
regs[0] |= 12;
bitcount = 0;
latch = 0;
update_prg();
return;
}
latch |= ((value & 1) << bitcount++);
if (bitcount != 5)
return;
int regnum = (address >> 13) & 3;
regs[regnum] = latch;
bitcount = 0;
latch = 0;
switch (regnum)
{
case 0:
update_mirror();
update_prg();
update_chr();
break;
case 1:
update_chr();
update_prg();
break;
case 2:
update_chr();
break;
case 3:
update_prg();
break;
}
}
static void map_getstate(uint8 *state)
{
state[0] = regs[0];
state[1] = regs[1];
state[2] = regs[2];
state[3] = regs[3];
state[4] = bitcount;
state[5] = latch;
}
static void map_setstate(uint8 *state)
{
regs[0] = state[0];
regs[1] = state[1];
regs[2] = state[2];
regs[3] = state[3];
bitcount = state[4];
latch = state[5];
}
static void map_init(rom_t *cart)
{
prg_banks = cart->prg_rom_banks / 2;
bitcount = 0;
latch = 0;
regs[0] = 31;
regs[1] = 0;
regs[2] = 0;
regs[3] = 0;
update_mirror();
update_chr();
update_prg();
}
