static struct
{
uint8 counter;
uint8 latch;
uint8 enabled;
} irq;
static uint32 reg8000;
static uint16 vrombase;
static bool fourscreen;
static void map_write(uint32 address, uint8 value)
{
switch (address & 57345)
{
case 32768:
reg8000 = value;
vrombase = (value & 128) ? 4096 : 0;
mmc_bankrom(8, (value & 64) ? 32768 : 49152, -2);
break;
case 32769:
switch (reg8000 & 7)
{
case 0:
value &= 254;
mmc_bankvrom(1, vrombase ^ 0, value);
mmc_bankvrom(1, vrombase ^ 1024, value + 1);
break;
case 1:
value &= 254;
mmc_bankvrom(1, vrombase ^ 2048, value);
mmc_bankvrom(1, vrombase ^ 3072, value + 1);
break;
case 2:
mmc_bankvrom(1, vrombase ^ 4096, value);
break;
case 3:
mmc_bankvrom(1, vrombase ^ 5120, value);
break;
case 4:
mmc_bankvrom(1, vrombase ^ 6144, value);
break;
case 5:
mmc_bankvrom(1, vrombase ^ 7168, value);
break;
case 6:
mmc_bankrom(8, (reg8000 & 64) ? 49152 : 32768, value);
break;
case 7:
mmc_bankrom(8, 40960, value);
break;
}
break;
case 40960:
if (fourscreen)
ppu_setmirroring(PPU_MIRROR_FOUR);
else if (value & 1)
ppu_setmirroring(PPU_MIRROR_HORI);
else
ppu_setmirroring(PPU_MIRROR_VERT);
break;
case 40961:
break;
case 49152:
irq.latch = value;
break;
case 49153:
irq.counter = 0;
break;
case 57344:
irq.enabled = false;
break;
case 57345:
irq.enabled = true;
break;
default:
MESSAGE_DEBUG("map004: unhandled write: address=%p, value=0x%x\n", (void*)address, value);
break;
}
}
static void map_hblank(nes_t *nes)
{
if (nes->scanline > 240)
return;
if (!ppu_enabled())
return;
if (irq.counter == 0)
irq.counter = irq.latch;
else
irq.counter--;
if (irq.enabled && irq.counter == 0)
nes6502_irq();
}
static void map_getstate(uint8 *state)
{
state[0] = irq.counter;
state[1] = irq.latch;
state[2] = irq.enabled;
state[3] = reg8000;
}
static void map_setstate(uint8 *state)
{
irq.counter =state[0];
irq.latch = state[1];
irq.enabled = state[2];
map_write(32768, state[3]);
}
static void map_init(rom_t *cart)
{
irq.enabled = irq.counter = irq.latch = 0;
reg8000 = vrombase = 0;
fourscreen = cart->fourscreen;
if (cart->mapper_number != 4)
{
if (cart->chr_rom_banks > 0)
{
MESSAGE_INFO("Using MMC3 variant, growing CHR-RAM to match CHR-ROM...\n");
cart->chr_ram = realloc(cart->chr_ram, 8192 * cart->chr_rom_banks);
cart->chr_ram_banks = cart->chr_rom_banks;
cart->chr_rom_banks = 0;
}
memcpy(cart->chr_ram, cart->chr_rom, 8192 * cart->chr_ram_banks);
mmc_bankchr(8, 0, 0, CHR_RAM);
}
}
