#define VRC_PBANK(bank, value, high) \
do { \
if ((high)) \
highprgnybbles[(bank)] = (value) & 15; \
else \
lowprgnybbles[(bank)] = (value) & 15; \
mmc_bankrom(8, 32768 + ((bank) << 13), (highprgnybbles[(bank)] << 4)+lowprgnybbles[(bank)]); \
} while (0)
#define VRC_VBANK(bank, value, high) \
{ \
if ((high)) \
highnybbles[(bank)] = (value) & 15; \
else \
lownybbles[(bank)] = (value) & 15; \
mmc_bankvrom(1, (bank) << 10, (highnybbles[(bank)] << 4)+lownybbles[(bank)]); \
}
