#define RAM_AUTO_INCREMENT 128
#define RAM_ADDR_MASK 127
#define SOUND_STEP 256
typedef struct
{
uint32 frequency;
uint32 length;
uint32 phase;
uint32 offset;
uint32 volume;
uint32 period;
uint32 enable;
} chan_t;
typedef struct map019_s
{
rom_t *cart;
uint8 ram[128];
uint8 address;
struct {
uint16 counter;
uint16 enabled;
} irq;
struct {
chan_t channels[8];
uint8 changed;
uint8 enable;
} sound;
uint8 nt_map[4];
} map019_t;
static map019_t *map019;
static void sound_prepare(void)
{
const nes_t *nes = nes_getptr();
uint32 chan_enable = ((map019->ram[127] >> 4) & 7) + 1;
uint32 z = ((uint64)nes->apu->sample_rate * (chan_enable * 15 * 32 * 32768) * SOUND_STEP) / nes->cpu_clock;
for (size_t i = 0; i < 8; i++)
{
chan_t *chan = &map019->sound.channels[i];
uint8 *regs = &map019->ram[64 + i * 8];
chan->frequency = regs[0] | (regs[2] << 8) | ((regs[4] & 3) << 16);
chan->length = 256 - (regs[4] & 252);
chan->phase = regs[1] | (regs[3] << 8) | (regs[5] << 16);
chan->offset = regs[6];
chan->volume = regs[7] & 15;
chan->period = chan->frequency ? (z / chan->frequency) : (1);
chan->enable = (chan->frequency != 0 && i >= (8 - chan_enable));
}
map019->sound.changed = false;
}
static int sound_process(void)
{
int active = 0;
int sample = 0;
for (size_t i = 0; i < 8; i++)
{
chan_t *chan = &map019->sound.channels[i];
if (!chan->enable)
continue;
active++;
for (size_t j = 0; j < 16; ++j)
{
int index = chan->offset + ((chan->phase / chan->period) % chan->length);
int value = map019->ram[(index >> 1) & 63];
if (index & 1)
value >>= 4;
sample += ((value & 15) - 8) * chan->volume;
chan->phase += SOUND_STEP;
}
uint8 *regs = &map019->ram[64 + i * 8];
regs[1] = chan->phase;
regs[3] = chan->phase >> 8;
regs[5] = chan->phase >> 16;
}
if (!active)
return 0;
return sample << 1;
}
