case 57345:
case 57348:
case 57472: VRC_VBANK(7,value,0); break;
case 57347:
case 57350:
case 57536: VRC_VBANK(7,value,1); break;
case 61440:
irq.latch &= 240;
irq.latch |= (value & 15);
break;
case 61442:
case 61504:
irq.latch &= 15;
irq.latch |= ((value & 15) << 4);
break;
case 61444:
case 61441:
