static struct
{
bool enabled;
uint8 counter;
uint8 reload;
} irq;
static void map_hblank(nes_t *nes)
{
if (irq.enabled && irq.counter)
{
if (0 == --irq.counter)
{
nes6502_irq();
irq.enabled = false;
}
}
}
static void map_write(uint32 address, uint8 value)
{
int range = (address >> 13) - 4;
switch (range)
{
case 0:
irq.enabled = false;
irq.counter = irq.reload;
break;
case 1:
irq.enabled = true;
break;
case 3:
mmc_bankrom(8, 49152, value & 7);
break;
default:
break;
}
}
