void nes6502_nmi(void)
{
if (cpu.jammed)
return;
DECLARE_LOCAL_REGS();
GET_GLOBAL_REGS();
NMI_PROC();
STORE_LOCAL_REGS();
cpu.burn_cycles += INT_CYCLES;
}
void nes6502_irq(void)
{
if (cpu.jammed)
return;
if (cpu.p_reg & I_FLAG)
{
cpu.int_pending = 1;
}
else
{
DECLARE_LOCAL_REGS();
GET_GLOBAL_REGS();
IRQ_PROC();
STORE_LOCAL_REGS();
cpu.burn_cycles += INT_CYCLES;
}
}
void nes6502_irq_clear(void)
{
cpu.p_reg &= I_FLAG;
}
void nes6502_burn(int cycles)
{
cpu.burn_cycles += cycles;
}
void nes6502_reset(void)
{
cpu.zp = cpu.pages[0] + 0;
cpu.stack = cpu.pages[0] + 256;
cpu.p_reg = Z_FLAG | R_FLAG | I_FLAG;
cpu.pc_reg = readword(RESET_VECTOR);
cpu.int_pending = false;
cpu.jammed = false;
cpu.burn_cycles = RESET_CYCLES;
}
nes6502_t *nes6502_init(uint8 **memmap)
{
memset(&cpu, 0, sizeof(nes6502_t));
cpu.pages = memmap;
return &cpu;
}
void nes6502_shutdown(void)
{
}
