static int dis_show_code(char *buf, int optype)
{
char *dest = buf + sprintf(buf, "%02X ", mem_getbyte(pc_reg));
switch (optype)
{
case _imp:
case _acc:
dest += sprintf(dest, " ");
break;
case _rel:
case _imm:
case _zero:
case _zero_x:
case _zero_y:
case _ind_y:
case _ind_x:
dest += sprintf(dest, "%02X ", mem_getbyte(pc_reg + 1));
break;
case _abs:
case _abs_x:
case _abs_y:
case _ind:
dest += sprintf(dest, "%02X %02X ", mem_getbyte(pc_reg + 1), mem_getbyte(pc_reg + 2));
break;
}
return (int) (dest - buf);
}
static int dis_show_op(char *buf, char *opstr, int optype)
{
char *dest = buf;
dest += dis_show_code(dest, optype);
dest += sprintf(dest, "%s ", opstr);
switch(optype)
{
case _imp: dest += sprintf(dest, " "); break;
case _acc: dest += dis_show_acc(dest); break;
case _rel: dest += dis_show_relative(dest); break;
case _imm: dest += dis_show_immediate(dest); break;
case _abs: dest += dis_show_abs(dest); break;
case _abs_x: dest += dis_show_abs_x(dest); break;
case _abs_y: dest += dis_show_abs_y(dest); break;
case _zero: dest += dis_show_zero(dest); break;
case _zero_x: dest += dis_show_zero_x(dest); break;
case _zero_y: dest += dis_show_zero_y(dest); break;
case _ind: dest += dis_show_ind(dest); break;
case _ind_x: dest += dis_show_ind_x(dest); break;
case _ind_y: dest += dis_show_ind_y(dest); break;
}
return (int) (dest - buf);
}
